-- 1b. The delete list, with the evidence
-- READ-ONLY
--
-- GENERATED from 590-proquest-ebc-batch-removal/README.md by tools/Build-SolutionDocs.ps1.
-- Do not edit this file - edit the README and re-run the script.
-- The README carries the reasoning, review gates and caveats.

SELECT
    bc.[bib#],
    bc.create_user,
    DATEADD(day, bc.create_date, CAST('1970-01-01' AS DATETIME)) AS [created],
    CASE WHEN EXISTS (
            SELECT 1 FROM bib e
            WHERE e.[bib#] = bc.[bib#]
              AND e.tag = '035'
              AND e.text COLLATE Latin1_General_CS_AS LIKE '%EBC[0-9]%')
         THEN 'Y' ELSE 'N' END                                  AS [has_ebc_035],
    (SELECT COUNT(*) FROM item i WHERE i.[bib#] = bc.[bib#])    AS [items_deleted_by_k]
FROM bib_control bc
WHERE bc.create_user = 'CATALOGER'
  AND bc.create_date = DATEDIFF(day, '1970-01-01', '2026-10-26')
  AND EXISTS (
        SELECT 1 FROM bib p
        WHERE p.[bib#] = bc.[bib#]
          AND p.tag = '590'
          AND p.text LIKE '%ProQuest%')
ORDER BY bc.[bib#];
